parameters.jsCode:
// Läser in formulärdata, städar den, avgör om den är giltig
// och räknar ut vilken väg förfrågan ska ta.
const ut = [];

for (const item of $input.all()) {
  // Webhook-noden lägger POST-innehållet under .body
  const d = item.json.body ?? item.json;

  const namn = String(d.namn ?? '').trim();
  const epost = String(d.epost ?? '').trim().toLowerCase();
  const telefon = String(d.telefon ?? '').trim();
  const jobbtyp = String(d.jobbtyp ?? '').trim();
  const beskrivning = String(d.beskrivning ?? '').trim();
  const budgetText = String(d.budgetText ?? '').trim();
  const budgetMin = Number(d.budgetMin ?? -1);
  const honungsfalla = String(d.foretag ?? '').trim();

  // --- Kontroller -------------------------------------------------
  const epostOk = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(epost);
  const spam = honungsfalla.length > 0;            // dolt fält = bott
  const komplett =
    namn.length >= 2 &&
    epostOk &&
    jobbtyp !== '' &&
    budgetText !== '' &&
    beskrivning.length >= 10 &&
    Number.isFinite(budgetMin) && budgetMin >= 0;

  const status = spam ? 'spam' : (komplett ? 'ok' : 'ogiltig');

  // --- Kategori utifrån budget ------------------------------------
  let kategori = 'Litet jobb';
  if (budgetMin >= 150000) kategori = 'Stort jobb';
  else if (budgetMin >= 25000) kategori = 'Mellanstort jobb';

  // --- Bekräftelse som visas på sidan -----------------------------
  const fornamn = namn.split(' ')[0] || 'du';
  const meddelanden = {
    'Stort jobb': 'Din förfrågan har gått direkt till Sara, vår säljansvariga. Hon hör av sig inom ett arbetsdygn för att boka ett platsbesök.',
    'Mellanstort jobb': 'Vi har tagit emot din förfrågan och återkommer inom ett arbetsdygn med en första bedömning.',
    'Litet jobb': 'Vi har tagit emot din förfrågan. Du får ett mejl med ett första svar inom några minuter.',
  };

  const nu = new Date();
  const referens =
    'NV-' + nu.toISOString().slice(0, 10).replace(/-/g, '') +
    '-' + Math.random().toString(36).slice(2, 6).toUpperCase();

  ut.push({
    json: {
      referens,
      mottagen: nu.toISOString(),
      namn,
      fornamn,
      epost,
      telefon,
      jobbtyp,
      budgetText,
      budgetMin,
      beskrivning,
      kategori,
      status,
      rubrik: 'Tack, ' + fornamn + '!',
      svarsmeddelande: meddelanden[kategori],
    },
  });
}

return ut;

